/*
 * Workspace slugs and the paths built from them. No Next.js or request imports, so scripts such as
 * `npm run demo:seed` print the same links the app routes to; `access.ts` adds the request checks.
 */

export const WORKSPACE_SECTIONS = [
  "timeline",
  "dashboard",
  "connections",
  "alerts",
  "projects",
  "settings",
] as const;

export type WorkspaceSection = (typeof WORKSPACE_SECTIONS)[number];

// Slugs are generated by the database (random lowercase base32), never typed by people, so
// anything else is rejected before it reaches a query or a redirect target.
const SLUG_PATTERN = /^[a-z0-9]{1,64}$/;

export function isWorkspaceSlug(slug: string): boolean {
  return SLUG_PATTERN.test(slug);
}

/** Path to a section of a workspace. Only call with a slug that passed `isWorkspaceSlug`. */
export function workspacePath(slug: string, section: WorkspaceSection): string {
  return `/w/${slug}/${section}`;
}

/**
 * Where a workspace opens: `/app`, `/w/<slug>`, the switcher, and the return after sign-in all
 * land here. The timeline, because it is the live pulse of the project (deploys, payments,
 * alerts as they happen); the dashboard's totals are one click away (#135).
 */
export function workspaceHome(slug: string): string {
  return workspacePath(slug, "timeline");
}

/** The yearly stack summary of one calendar year (#151). */
export function yearInReviewPath(slug: string, year: number): string {
  return `/w/${slug}/year/${year}`;
}

/** The id of the settings page's key name field, which the create API key link targets (#265). */
export const CREATE_API_KEY_FIELD_ID = "create-api-key";

/** Settings, scrolled to the create API key form; the form focuses its name field when it opens here. */
export function createApiKeyPath(slug: string): string {
  return `${workspacePath(slug, "settings")}#${CREATE_API_KEY_FIELD_ID}`;
}

/** The id of the settings page's AI assistants heading (#163), which the setup checklist links to (#674). */
export const ASSISTANT_SETUP_ID = "assistants-title";

/** Settings, scrolled to the AI assistants section, where owners and admins create the assistant's key. */
export function assistantSetupPath(slug: string): string {
  return `${workspacePath(slug, "settings")}#${ASSISTANT_SETUP_ID}`;
}

/**
 * Fragments on the alert settings page that links land on (#343): each section's heading, and the
 * "New" button of each create form, which opens its form when the page loads with that fragment.
 * The alerts page itself is the inbox of triggered alerts.
 */
export const ALERT_SETTINGS_IDS = {
  suggested: "suggested-alerts-title",
  rules: "alert-rules-title",
  newRule: "add-alert-rule",
  budgets: "budgets-title",
  newBudget: "add-budget",
  emails: "alert-emails",
  channels: "alert-channels",
  newChannel: "add-alert-channel",
  unusual: "unusual-activity-title",
} as const;

export type AlertSettingsId = (typeof ALERT_SETTINGS_IDS)[keyof typeof ALERT_SETTINGS_IDS];

const ALERT_SETTINGS_ID_SET: ReadonlySet<string> = new Set(Object.values(ALERT_SETTINGS_IDS));

/** The alerts inbox's query: `acknowledged=show` includes acknowledged alerts, and the list's pager cursor. */
export type AlertsInboxQuery = { acknowledged: "show" | null; alertsAfter: string | null };

/** Alert settings' query: the rules and budgets pagers' cursors. The inbox's own query stays there. */
export type AlertSettingsQuery = { rulesAfter: string | null; budgetsAfter: string | null };

/**
 * A link from a page's whole query and an optional fragment. Every pager and filter link on the
 * alerts pages passes its page's query with only its own part changed, so paging one list keeps
 * every other list's place (#316). Callers check that literal with `satisfies AlertsInboxQuery` or
 * `satisfies AlertSettingsQuery`, so a misspelled key fails to compile instead of adding a stray
 * parameter. Null and empty values are left out, so a first page adds no cursor to the link.
 */
export function pathWithQuery(path: string, query: Readonly<Record<string, string | null>>, fragment?: string): string {
  const params = new URLSearchParams();
  for (const [name, value] of Object.entries(query)) {
    if (value !== null && value !== "") params.set(name, value);
  }
  const text = params.toString();
  return `${path}${text === "" ? "" : `?${text}`}${fragment === undefined ? "" : `#${fragment}`}`;
}

/** Alert settings: rules, budgets, unusual spend and usage, alert emails, and channels (#343). */
export function alertSettingsPath(slug: string, id?: AlertSettingsId): string {
  const path = `${workspacePath(slug, "alerts")}/settings`;
  return id === undefined ? path : `${path}#${id}`;
}

/**
 * Where a link written for the alerts page before its settings moved (#343) belongs, from the
 * page's `location.search` and `location.hash`: alert settings, with the settings pagers' cursors
 * and the same fragment, when the fragment names a settings section. Null for any other fragment,
 * which stays on the inbox. Alert emails sent before the move link to `/alerts#alert-emails`.
 */
export function movedAlertSettingsHref(slug: string, search: string, hash: string): string | null {
  const id = hash.startsWith("#") ? hash.slice(1) : "";
  if (!ALERT_SETTINGS_ID_SET.has(id)) return null;
  const from = new URLSearchParams(search);
  const query: AlertSettingsQuery = { rulesAfter: from.get("rulesAfter"), budgetsAfter: from.get("budgetsAfter") };
  return pathWithQuery(alertSettingsPath(slug), query, id);
}
